rotate_extrude(angle=360, start=0, $fn=64)
  polygon([
    [0,0],   // Bottom centre, on the axis.
    [12,0],  // Outside edge of the base.
    [25,24], // Outside rim.
    [22,24], // Inside rim: cross the wall thickness.
    [10,3],  // Inside wall meets the floor.
    [0,3]    // Floor centre; the closing edge completes the base.
  ]);`),"A torus":Ae("A doughnut-shaped ring with a 6 mm thick circular tube and an approximately 26 mm central opening.","Change translate([16,0]) to translate([22,0]); the ring grows wider while tube thickness stays the same.",`
