  let(h=6+i*4, r=2+i/2) // Temporary dimensions for this iteration only.
    translate([i*12,0,0])
      cylinder(h=h, r=r, $fn=24); // Use those named dimensions.`),"A reusable hollow post":Ae("An 18 mm tall hollow post with outer radius 6 and wall thickness 2.","Call post(h=18,wall=1); the bore widens while the outside stays the same.",`
